<?php
namespace Tests\Feature;
use App\Models\Customer;use App\Models\LoyaltyRule;use App\Models\Order;use App\Models\User;use App\Services\LoyaltyService;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class LoyaltyFlowTest extends TestCase{use RefreshDatabase;
 public function test_multiple_rules_award_and_points_redeem_fifo():void{$this->seed();$u=User::first();$c=Customer::create(['branch_id'=>$u->branch_id,'name'=>'Ana','phone'=>'555']);LoyaltyRule::create(['branch_id'=>$u->branch_id,'name'=>'Por cien','type'=>'per_amount','threshold'=>100,'points'=>10,'expires_days'=>30]);LoyaltyRule::create(['branch_id'=>$u->branch_id,'name'=>'Por pedido','type'=>'per_order','threshold'=>1,'points'=>3]);$o=Order::create(['branch_id'=>$u->branch_id,'user_id'=>$u->id,'customer_id'=>$c->id,'order_date'=>today(),'daily_number'=>1,'status'=>'delivered','type'=>'pickup','total'=>250]);$service=app(LoyaltyService::class);$service->award($o);$this->assertEquals(23,$c->points_balance);$service->redeem($c,8,$u,$o,8);$this->assertEquals(15,$c->fresh()->points_balance);$this->assertDatabaseHas('loyalty_redemptions',['customer_id'=>$c->id,'points'=>8]);}
 public function test_courtesy_does_not_award_by_default():void{$this->seed();$u=User::first();$c=Customer::create(['branch_id'=>$u->branch_id,'name'=>'Luis','phone'=>'777']);LoyaltyRule::create(['branch_id'=>$u->branch_id,'name'=>'Pedido','type'=>'per_order','threshold'=>1,'points'=>5]);$o=Order::create(['branch_id'=>$u->branch_id,'user_id'=>$u->id,'customer_id'=>$c->id,'order_date'=>today(),'daily_number'=>1,'status'=>'delivered','type'=>'pickup','total'=>100,'courtesy'=>true]);app(LoyaltyService::class)->award($o);$this->assertEquals(0,$c->points_balance);}
}
